  &id                OBJECT IDENTIFIER UNIQUE,
  &Params            OPTIONAL,
  &paramPresence     ParamOptions DEFAULT absent,
  &smimeCaps         SMIME-CAPS OPTIONAL
}
WITH SYNTAX {
  IDENTIFIER &id
  [PARAMS [TYPE &Params] ARE &paramPresence]
  [SMIME-CAPS &smimeCaps]
}

